(() => {
  function roundOrderToCases(input) {
    const allowed = ["orderUnits", "caseSize"];
    for (const key of Object.keys(input)) {
      if (!allowed.includes(key)) {
        throw new Error("unknown field: " + key);
      }
    }
    const { orderUnits, caseSize } = input;
    if (typeof orderUnits !== "number" || !Number.isFinite(orderUnits) || orderUnits <= 0) {
      throw new Error("orderUnits of 0 or less, or not a finite number, is not yet specified (AC-4): confirm with requester");
    }
    if (typeof caseSize !== "number" || !Number.isFinite(caseSize) || caseSize <= 0) {
      throw new Error("caseSize of 0 or less, or not a finite number, is not yet specified (AC-4): confirm with requester");
    }
    const cases = Math.max(2, Math.ceil(orderUnits / caseSize));
    return { cases, shippedUnits: cases * caseSize };
  }
  return { roundOrderToCases };
})()

