build.unitScript:
test("order of 25 units with case size 12 ships 3 cases and 36 units", () => {
  assert.deepEqual(code.roundOrderToCases({ orderUnits: 25, caseSize: 12 }), { cases: 3, shippedUnits: 36 });
});
test("order of 5 units with case size 12 is raised to the 2-case minimum, 24 units", () => {
  assert.deepEqual(code.roundOrderToCases({ orderUnits: 5, caseSize: 12 }), { cases: 2, shippedUnits: 24 });
});
test("order of 24 units with case size 12 is an exact multiple and ships 2 cases, 24 units", () => {
  assert.deepEqual(code.roundOrderToCases({ orderUnits: 24, caseSize: 12 }), { cases: 2, shippedUnits: 24 });
});
test("exact multiple above the minimum (36 units, case size 12) is not rounded further: 3 cases, 36 units", () => {
  assert.deepEqual(code.roundOrderToCases({ orderUnits: 36, caseSize: 12 }), { cases: 3, shippedUnits: 36 });
});
test("one unit over a whole case (37 units, case size 12) rounds up to 4 cases, 48 units", () => {
  assert.deepEqual(code.roundOrderToCases({ orderUnits: 37, caseSize: 12 }), { cases: 4, shippedUnits: 48 });
});
test("an input with an extra field throws unknown field with that field name", () => {
  assert.throws(() => code.roundOrderToCases({ orderUnits: 25, caseSize: 12, store: "A" }), /unknown field: store/);
});

